var IDS=["activity--work", "artifacts--code", "artifacts--detail", "artifacts--share", "conversation--approval", "project--work", "projects", "projects--new", "routines--new", "settings-account", "settings-appearance", "settings-billing", "settings-billing--plan", "settings-connections", "settings-devices", "settings-general", "settings-notifications", "settings-shortcuts", "settings-voice", "signin"];
var ids=IDS;function descendants(l){var a=[];(l.layers||[]).forEach(c=>{a.push(c);a=a.concat(descendants(c));});return a;}['Light','Dark'].forEach(ap=>{var p=H.page('Proto iOS '+ap);ids.forEach(id=>{var s=p.layers.find(l=>l.name==='Screen/ios/'+ap+'/Clean/'+id);var all=descendants(s);var texts=all.filter(l=>l.name==='text'&&l.stackLayout);var indicators=all.filter(l=>l.name==='home-indicator-overlay');var rows=all.filter(l=>l.parent&&l.parent.name==='rows'&&l.stackLayout&&l.name.indexOf('sep')!==0);var bad=all.filter(l=>l.type==='Text'&&l.parent&&l.parent!==p&&(l.frame.x<-.1||l.frame.y<-.1||l.frame.x+l.frame.width>l.parent.frame.width+.1||l.frame.y+l.frame.height>l.parent.frame.height+.1));console.log(JSON.stringify({id:id,appearance:ap,frame:s.id,geometry:s.frame,alignmentBad:texts.filter(t=>t.stackLayout.alignItems!==0).map(t=>t.id),overlay:indicators.map(t=>({f:t.frame,index:t.index,top:s.layers.length-1})),grabbers:all.filter(l=>l.name==='grabber').map(l=>l.frame),rows:rows.map(l=>({name:l.name,h:l.frame.height,text:l.layers.find(t=>t.name==='text')?.frame,chevron:l.layers.find(t=>t.name==='sf:chevron_right')?.frame})),overflow:bad.map(l=>({t:l.text,f:l.frame,p:l.parent.frame}))}));});});